$ErrorActionPreference='SilentlyContinue'
$host.UI.RawUI.WindowTitle='S100A8 six-trajectory analysis progress - display only'
$root=Split-Path -Parent (Split-Path -Parent $MyInvocation.MyCommand.Path);$dir=Join-Path $root 'comparative_analysis_v1'
while($true){Clear-Host;Write-Host 'S100A8 six-trajectory analysis' -ForegroundColor Cyan;Write-Host("Updated: {0}"-f(Get-Date).ToString('yyyy-MM-dd HH:mm:ss'));$p=Join-Path $dir 'CURRENT_STAGE.txt';if(Test-Path $p){Write-Host("Stage: {0}"-f((Get-Content $p)-join' '))};$done=(Get-ChildItem (Join-Path $dir 'per_trajectory') -Filter '*.done' -Recurse -ErrorAction SilentlyContinue).Count;Write-Host("Completed metric units: $done / 27");$runner=Get-CimInstance Win32_Process -Filter "Name='powershell.exe'"|Where-Object{$_.CommandLine-match'run_extended_metrics_v1\.ps1'};if($runner){Write-Host 'ANALYSIS RUNNING' -ForegroundColor Green}else{Write-Host 'Analysis stopped / completed' -ForegroundColor Yellow};Write-Host 'Closing this display does not stop analysis.' -ForegroundColor DarkGray;Start-Sleep 5}
